#!/usr/bin/env python3
"""Check MIR runner generated by native modular compiler (no flat runner)."""
from pathlib import Path
import shutil
import subprocess
import tempfile

from build_support import BuildCache, compile_c, execute, require_cc
from project_paths import executable_path, ROOT, normalize_newlines


def main() -> None:
	cache = BuildCache(shutil.which('clang') or require_cc())
	compiler = cache.native_tool('modular_cli')
	runner = cache.mir_runner()
	with tempfile.TemporaryDirectory() as directory:
		work = Path(directory)
		generated = work / 'run_cli.c'
		execute([str(compiler), '--module-root', str(ROOT / 'src'), 'run_cli', str(generated)])
		other = executable_path(work / 'run_cli')
		compile_c(cache.cc, generated, other, cache.runtime())
		modules = work / 'sample'
		modules.mkdir()
		(modules / 'Math.sirius').write_text('export def triple(x: i64) -> i64\n\treturn x * 3\n', encoding='utf-8')
		(modules / 'Main.sirius').write_text('import Math alias Math\ndef main() -> i64\n\tprint(Math.triple(14))\n\treturn 0\n', encoding='utf-8')
		primary_library = work / 'primary.smirl'
		other_library = work / 'other.smirl'
		execute([str(runner), '--build-modules', str(modules), 'Main', str(primary_library)])
		execute([str(other), '--build-modules', str(modules), 'Main', str(other_library)])
		assert primary_library.read_bytes() == other_library.read_bytes(), 'native runners disagree on MIR'
		output = subprocess.run([str(runner), '--entry', 'M_4_Main_4_main', '--load-lib', str(primary_library)], capture_output=True)
		assert output.returncode == 0 and normalize_newlines(output.stdout) == b'42\n', output
		primary_c, other_c = work / 'primary.c', work / 'other.c'
		execute([str(runner), '--emit-linked-c', str(primary_library), 'M_4_Main_4_main', str(primary_c)])
		execute([str(other), '--emit-linked-c', str(other_library), 'M_4_Main_4_main', str(other_c)])
		assert primary_c.read_bytes() == other_c.read_bytes(), 'native runners disagree on emitted C'
		print('PASS independent native MIR runner: link, interpret and C emission')


if __name__ == '__main__':
	main()
